import { and, eq } from "drizzle-orm";
import { db } from "../db";
import { customers, invoices } from "../schema";
import { protectedProcedure, router } from "../trpc";
import { z } from "zod";

export const invoicesRouter = router({
  summaries: protectedProcedure
    .input(z.object({ invoiceIds: z.array(z.string()).max(50) }))
    .query(async ({ ctx, input }) => {
      const out = [];
      for (const invoiceId of input.invoiceIds) {
        const [row] = await db
          .select({ id: invoices.id, total: invoices.totalCents, customer: customers.name })
          .from(invoices)
          .innerJoin(customers, eq(customers.id, invoices.customerId))
          .where(and(eq(invoices.id, invoiceId), eq(invoices.orgId, ctx.orgId)));
        if (row) out.push(row);
      }
      return out;
    }),
});

