import crypto from "node:crypto";
import type { FastifyInstance } from "fastify";

export async function loginRoutes(app: FastifyInstance) {
  app.post<{ Body: { email: string; password: string } }>("/login", async (request, reply) => {
    const user = await app.db.users.findByEmail(request.body.email);
    if (!user) return reply.code(401).send({ error: "invalid credentials" });

    const hash = crypto.pbkdf2Sync(request.body.password, user.salt, 310000, 32, "sha256");
    if (!crypto.timingSafeEqual(hash, Buffer.from(user.passwordHash, "hex"))) {
      return reply.code(401).send({ error: "invalid credentials" });
    }
    return reply.send({ token: app.jwt.sign({ sub: user.id }) });
  });
}

